 $('lm-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),to=String(f.get('to')||''),count=to.split(/[\\s,;]+/).filter(Boolean).length;if(!confirm('Add '+count+' message'+(count===1?'':'s')+' to the sending list?'))return;const from=$('lm-from').value==='custom'?f.get('customFrom'):$('lm-from').value,btn=$('lm-send');btn.disabled=true;try{const d=await api('/api/admin/send',{method:'POST',body:JSON.stringify({to,fromEmail:from,fromName:f.get('fromName'),subject:f.get('subject'),text:f.get('text')})});dlg.close();play('confirm');alert(d.message||'Your messages have been added to the sending list.');folder='sent';document.querySelector('[data-folder="sent"]').click();loadCounts();loadNotifications();}catch(err){$('lm-error').textContent=err.message;$('lm-error').hidden=false;}finally{btn.disabled=false;}});
 $('lm-ai').addEventListener('click',async()=>{if(!selected)return;const b=$('lm-ai');b.disabled=true;b.textContent='Preparing\u2026';try{const d=await api('/api/admin/mail/'+selected.id+'/suggest',{method:'POST',body:'{}'});$('lm-suggestion').value=d.suggestion;$('lm-ai-result').hidden=false;play('confirm');}catch(e){alert(e.message);}finally{b.disabled=false;b.textContent='Suggest a reply';}});
