 document.addEventListener('submit',async e=>{if(e.target?.id!=='lm-profile-form')return;e.preventDefault();try{await api('/api/account/profile',{method:'PATCH',body:JSON.stringify({fullName:$('lm-full-name').value})});$('lm-profile-status').textContent='Your name has been saved.';play('confirm');}catch(err){$('lm-profile-status').textContent=err.message;}});
 $('logout-link')?.addEventListener('click',async e=>{e.preventDefault();if(!confirm('Log out of LeadMASTER?'))return;try{await api('/api/auth/logout',{method:'POST',body:'{}'});}finally{location.replace('/login.html');}});
async function loadProfile(){try{const d=await api('/api/account/profile');if($('lm-full-name'))$('lm-full-name').value=d.fullName||'';}catch(e){if($('lm-profile-status'))$('lm-profile-status').textContent=e.message;}}
