    const report = { reportDate, timeZone, generatedAt: (/* @__PURE__ */ new Date()).toISOString(), overall: summary.overall, summary, checks };
    await persistRun(env, reportKey, {
      status: "failed",
      completedAt: Date.now(),
      summary,
      report,
      emailStatus: "not_attempted",
      messageId,
      error: safeString(error62?.message || error62, 800)
    });
